const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define Antarctica region (bounding box covering Antarctica)
  var antarctica = ee.Geometry.Rectangle([-180, -90, 180, -60], null, false);

  // Date ranges
  var augStart = '2024-08-26';
  var augEnd = '2024-08-31'; // Exclusive, so up to Aug 30
  var sepStart = '2024-09-26';
  var sepEnd = '2024-10-01'; // Exclusive, so up to Sep 30

  // Function to compute ozone hole area for a given date range
  function getOzoneHoleArea(startDate, endDate) {
    // Load OMI ozone data
    var collection = ee.ImageCollection('OMI/Aura/O3_TCL_1r')
      .filterDate(startDate, endDate)
      .filterBounds(antarctica)
      .select('O3');

    var count = collection.size();
    var countInfo = count.getInfo();
    console.log(`${startDate} to ${endDate} Images: ${countInfo}`);

    if (countInfo === 0) {
      // No data for this period
      return null;
    }

    // Compute mean ozone over the period
    var meanO3 = collection.mean();

    // Create mask for ozone hole (O3 < 220 Dobson units)
    var ozoneHoleMask = meanO3.lt(220);

    // Calculate area of ozone hole in km²
    // First, get pixel area in km² (pixelArea gives m², divide by 1e6 for km²)
    var area = ozoneHoleMask.multiply(ee.Image.pixelArea().divide(1000000))
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: antarctica,
        scale: 10000, // Use 10km scale for ozone data
        maxPixels: 1e9
      }).get('O3');

    var areaValue = area.getInfo();

    // Count valid pixels in mask to check for C2
    var pixelCount = ozoneHoleMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: antarctica,
      scale: 10000,
      maxPixels: 1e9
    }).get('O3').getInfo();

    console.log(`Valid pixels: ${pixelCount}, Area: ${areaValue} km²`);

    return {
      area: areaValue,
      pixelCount: pixelCount,
      collectionSize: countInfo
    };
  }

  // 2. Data Acquisition & Check
  var augResult = getOzoneHoleArea(augStart, augEnd);
  var sepResult = getOzoneHoleArea(sepStart, sepEnd);

  // Check for C1: Empty Collection
  if (augResult === null || sepResult === null) {
    console.log(`August data available: ${augResult !== null}, September data available: ${sepResult !== null}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Check for C2: No Valid Pixels
  if (augResult.pixelCount === 0 || sepResult.pixelCount === 0) {
    console.log(`August valid pixels: ${augResult.pixelCount}, September valid pixels: ${sepResult.pixelCount}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // 3. Validation & Final Answer
  var augArea = augResult.area;
  var sepArea = sepResult.area;

  console.log(`August ozone hole area: ${augArea} km²`);
  console.log(`September ozone hole area: ${sepArea} km²`);

  // Check for C3: Calculation Failure
  if (augArea === null || sepArea === null || 
      isNaN(augArea) || isNaN(sepArea) ||
      augArea < 0 || sepArea < 0) {
    console.log("Invalid area calculation");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare areas
  if (sepArea > augArea) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
